      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.33;

/******************************************************************************\
* Author: Nick Mudge <nick@perfectabstractions.com> (https://twitter.com/mudgen)
* EIP-2535 Diamonds: https://eips.ethereum.org/EIPS/eip-2535
*
* Adapted from diamond-1-hardhat (https://github.com/mudgen/diamond-1-hardhat), MIT:
* the cut, the loupe and a two-step ownership are functions of the diamond itself.
/******************************************************************************/

import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

import {IDiamondCut} from "./interfaces/IDiamondCut.sol";
import {IDiamondLoupe} from "./interfaces/IDiamondLoupe.sol";
import {IERC173} from "./interfaces/IERC173.sol";
import {LibDiamond} from "./libraries/LibDiamond.sol";

/// @title SteakhouseOperator
/// @notice Steakhouse's operator: an EIP-2535 diamond that the bots call, whose facets act on Morpho vaults under
/// one role table.
/// @dev The cut, the loupe and the two-step ownership are defined here and are immutable: they are registered in the
/// routing table under the diamond's own address, so the loupe reports them and no cut can replace or remove them.
/// Every other function is routed by the fallback to its facet. The constructor takes only the owner, so the init
/// code, and with one CREATE2 salt the address, is the same on every chain.
contract SteakhouseOperator is IDiamondCut, IDiamondLoupe, IERC173, IERC165 {
    error FunctionNotFound(bytes4 selector);
    error NotPendingOwner(address account);

    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);

    constructor(address initialOwner) {
        bytes4[] memory selectors = new bytes4[](10);
        selectors[0] = IDiamondCut.diamondCut.selector;
        selectors[1] = IDiamondLoupe.facets.selector;
        selectors[2] = IDiamondLoupe.facetFunctionSelectors.selector;
        selectors[3] = IDiamondLoupe.facetAddresses.selector;
        selectors[4] = IDiamondLoupe.facetAddress.selector;
        selectors[5] = IERC165.supportsInterface.selector;
        selectors[6] = IERC173.owner.selector;
        selectors[7] = IERC173.transferOwnership.selector;
        selectors[8] = SteakhouseOperator.pendingOwner.selector;
        selectors[9] = SteakhouseOperator.acceptOwnership.selector;
        LibDiamond.addFunctions(address(this), selectors);
        FacetCut[] memory cut = new FacetCut[](1);
        cut[0] = FacetCut({facetAddress: address(this), action: FacetCutAction.Add, functionSelectors: selectors});
        emit DiamondCut(cut, address(0), "");

        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        ds.supportedInterfaces[type(IERC165).interfaceId] = true;
        ds.supportedInterfaces[type(IDiamondCut).interfaceId] = true;
        ds.supportedInterfaces[type(IDiamondLoupe).interfaceId] = true;
        ds.supportedInterfaces[type(IERC173).interfaceId] = true;

        ds.contractOwner = initialOwner;
        emit OwnershipTransferred(address(0), initialOwner);
    }

    /// @notice Runs the function of the facet registered for the call's selector, with the diamond's storage.
    fallback() external payable {
        address facet = LibDiamond.diamondStorage().facetAddressAndSelectorPosition[msg.sig].facetAddress;
        if (facet == address(0)) revert FunctionNotFound(msg.sig);
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), facet, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    /// @notice Accepts ETH within a 2300-gas stipend: Morpho's public allocator pays its fees with `transfer`.
    receive() external payable {}

    // ---------------------------------------------------------------- cut

    /// @inheritdoc IDiamondCut
    /// @dev Owner only.
    function diamondCut(FacetCut[] calldata cuts, address init, bytes calldata initData) external {
        LibDiamond.enforceIsContractOwner();
        LibDiamond.diamondCut(cuts, init, initData);
    }

    // ---------------------------------------------------------------- loupe

    /// @inheritdoc IDiamondLoupe
    function facets() external view returns (Facet[] memory facets_) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 selectorCount = ds.selectors.length;
        // Sized for the worst case (one facet per selector), then trimmed.
        facets_ = new Facet[](selectorCount);
        uint16[] memory numFacetSelectors = new uint16[](selectorCount);
        uint256 numFacets = 0;
        for (uint256 selectorIndex; selectorIndex < selectorCount; selectorIndex++) {
            bytes4 selector = ds.selectors[selectorIndex];
            address facetAddress_ = ds.facetAddressAndSelectorPosition[selector].facetAddress;
            bool found = false;
            for (uint256 facetIndex; facetIndex < numFacets; facetIndex++) {
                if (facets_[facetIndex].facetAddress == facetAddress_) {
                    facets_[facetIndex].functionSelectors[numFacetSelectors[facetIndex]] = selector;
                    numFacetSelectors[facetIndex]++;
                    found = true;
                    break;
                }
            }
            if (found) continue;
            facets_[numFacets].facetAddress = facetAddress_;
            facets_[numFacets].functionSelectors = new bytes4[](selectorCount);
            facets_[numFacets].functionSelectors[0] = selector;
            numFacetSelectors[numFacets] = 1;
            numFacets++;
        }
        for (uint256 facetIndex; facetIndex < numFacets; facetIndex++) {
            uint256 numSelectors = numFacetSelectors[facetIndex];
            bytes4[] memory selectors = facets_[facetIndex].functionSelectors;
            assembly ("memory-safe") {
                mstore(selectors, numSelectors)
            }
        }
        assembly ("memory-safe") {
            mstore(facets_, numFacets)
        }
    }

    /// @inheritdoc IDiamondLoupe
    function facetFunctionSelectors(address facet) external view returns (bytes4[] memory facetFunctionSelectors_) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 selectorCount = ds.selectors.length;
        uint256 numSelectors = 0;
        facetFunctionSelectors_ = new bytes4[](selectorCount);
        for (uint256 selectorIndex; selectorIndex < selectorCount; selectorIndex++) {
            bytes4 selector = ds.selectors[selectorIndex];
            if (facet == ds.facetAddressAndSelectorPosition[selector].facetAddress) {
                facetFunctionSelectors_[numSelectors] = selector;
                numSelectors++;
            }
        }
        assembly ("memory-safe") {
            mstore(facetFunctionSelectors_, numSelectors)
        }
    }

    /// @inheritdoc IDiamondLoupe
    function facetAddresses() external view returns (address[] memory facetAddresses_) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 selectorCount = ds.selectors.length;
        facetAddresses_ = new address[](selectorCount);
        uint256 numFacets = 0;
        for (uint256 selectorIndex; selectorIndex < selectorCount; selectorIndex++) {
            address facetAddress_ = ds.facetAddressAndSelectorPosition[ds.selectors[selectorIndex]].facetAddress;
            bool found = false;
            for (uint256 facetIndex; facetIndex < numFacets; facetIndex++) {
                if (facetAddress_ == facetAddresses_[facetIndex]) {
                    found = true;
                    break;
                }
            }
            if (found) continue;
            facetAddresses_[numFacets] = facetAddress_;
            numFacets++;
        }
        assembly ("memory-safe") {
            mstore(facetAddresses_, numFacets)
        }
    }

    /// @inheritdoc IDiamondLoupe
    function facetAddress(bytes4 functionSelector) external view returns (address facetAddress_) {
        facetAddress_ = LibDiamond.diamondStorage().facetAddressAndSelectorPosition[functionSelector].facetAddress;
    }

    /// @inheritdoc IERC165
    function supportsInterface(bytes4 interfaceId) external view returns (bool) {
        return LibDiamond.diamondStorage().supportedInterfaces[interfaceId];
    }

    // ---------------------------------------------------------------- ownership

    /// @inheritdoc IERC173
    function owner() external view returns (address) {
        return LibDiamond.contractOwner();
    }

    /// @notice The account that may complete the current transfer of ownership with `acceptOwnership`.
    function pendingOwner() external view returns (address) {
        return LibDiamond.diamondStorage().pendingOwner;
    }

    /// @notice Starts a transfer of ownership, which `newOwner` completes with `acceptOwnership`. Owner only; zero
    /// cancels a pending transfer. Ownership can be transferred but never renounced.
    function transferOwnership(address newOwner) external {
        LibDiamond.enforceIsContractOwner();
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        ds.pendingOwner = newOwner;
        emit OwnershipTransferStarted(ds.contractOwner, newOwner);
    }

    /// @notice Completes a transfer of ownership; only the pending owner may call it.
    function acceptOwnership() external {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        if (msg.sender != ds.pendingOwner) revert NotPendingOwner(msg.sender);
        address previousOwner = ds.contractOwner;
        ds.contractOwner = msg.sender;
        ds.pendingOwner = address(0);
        emit OwnershipTransferred(previousOwner, msg.sender);
    }
}
