import {IDiamond} from "./IDiamond.sol";

interface IDiamondCut is IDiamond {
    /// @notice Adds, replaces or removes functions, then optionally runs an initialization.
    /// @param cuts The facet addresses, actions and function selectors.
    /// @param init The contract to delegatecall with `initData`; zero skips the initialization.
    /// @param initData The calldata of the initialization, usually a function call with its arguments.
    function diamondCut(FacetCut[] calldata cuts, address init, bytes calldata initData) external;
}
