*
* Adapted from diamond-1-hardhat (https://github.com/mudgen/diamond-1-hardhat), MIT.
/******************************************************************************/

/// @notice The loupe: which functions a diamond has and which facet runs each.
interface IDiamondLoupe {
    struct Facet {
        address facetAddress;
        bytes4[] functionSelectors;
    }

    /// @notice Every facet address with its function selectors.
    function facets() external view returns (Facet[] memory facets_);

    /// @notice The function selectors a facet runs.
    function facetFunctionSelectors(address facet) external view returns (bytes4[] memory facetFunctionSelectors_);

    /// @notice Every facet address.
    function facetAddresses() external view returns (address[] memory facetAddresses_);

    /// @notice The facet that runs a function; zero when the diamond has no such function.
    function facetAddress(bytes4 functionSelector) external view returns (address facetAddress_);
}
