pragma solidity 0.8.33;

/******************************************************************************\
* Author: Nick Mudge <nick@perfectabstractions.com> (https://twitter.com/mudgen)
* EIP-2535 Diamonds: https://eips.ethereum.org/EIPS/eip-2535
*
* Adapted from diamond-1-hardhat (https://github.com/mudgen/diamond-1-hardhat), MIT:
* storage in an ERC-7201 namespace, a two-step owner, and functions defined in the
* diamond itself that no cut can replace or remove.
/******************************************************************************/

import {IDiamond} from "../interfaces/IDiamond.sol";

error NoSelectorsProvidedForFacetForCut(address facetAddress);
error NotContractOwner(address user, address contractOwner);
error CannotAddSelectorsToZeroAddress(bytes4[] selectors);
error CannotUseDiamondAsFacet();
error NoBytecodeAtAddress(address contractAddress, string message);
error IncorrectFacetCutAction(uint8 action);
error CannotAddFunctionToDiamondThatAlreadyExists(bytes4 selector);
error CannotReplaceFunctionsFromFacetWithZeroAddress(bytes4[] selectors);
error CannotReplaceImmutableFunction(bytes4 selector);
error CannotReplaceFunctionWithTheSameFunctionFromTheSameFacet(bytes4 selector);
error CannotReplaceFunctionThatDoesNotExists(bytes4 selector);
error RemoveFacetAddressMustBeZeroAddress(address facetAddress);
error CannotRemoveFunctionThatDoesNotExist(bytes4 selector);
error CannotRemoveImmutableFunction(bytes4 selector);
error InitializationFunctionReverted(address initializationContractAddress, bytes data);

/// @notice The diamond's routing table, supported interfaces and owner, and the cut logic that edits the table.
/// @dev Functions defined in the diamond itself are registered with the diamond's own address as their facet. They
/// are immutable: a cut can neither replace nor remove them, nor register anything else under that address.
library LibDiamond {
    /// @dev keccak256(abi.encode(uint256(keccak256("steakhouse.operator.diamond")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 internal constant STORAGE_LOCATION = 0x097ce880f191a93320e3ba1d622d145a06ed1c4076820e39fd18e2d78a6aea00;

    struct FacetAddressAndSelectorPosition {
        address facetAddress;
        uint16 selectorPosition;
    }

    /// @custom:storage-location erc7201:steakhouse.operator.diamond
    struct DiamondStorage {
        /// @dev Function selector => the facet that runs it and the selector's position in `selectors`.
        mapping(bytes4 => FacetAddressAndSelectorPosition) facetAddressAndSelectorPosition;
        bytes4[] selectors;
        mapping(bytes4 => bool) supportedInterfaces;
        address contractOwner;
        address pendingOwner;
    }

    function diamondStorage() internal pure returns (DiamondStorage storage ds) {
        bytes32 position = STORAGE_LOCATION;
        assembly {
            ds.slot := position
        }
    }

    function contractOwner() internal view returns (address) {
        return diamondStorage().contractOwner;
    }

    function enforceIsContractOwner() internal view {
        address owner = diamondStorage().contractOwner;
        if (msg.sender != owner) revert NotContractOwner(msg.sender, owner);
    }

    function diamondCut(IDiamond.FacetCut[] memory cuts, address init, bytes memory initData) internal {
        for (uint256 facetIndex; facetIndex < cuts.length; facetIndex++) {
            bytes4[] memory functionSelectors = cuts[facetIndex].functionSelectors;
            address facetAddress = cuts[facetIndex].facetAddress;
            if (functionSelectors.length == 0) revert NoSelectorsProvidedForFacetForCut(facetAddress);
            IDiamond.FacetCutAction action = cuts[facetIndex].action;
            if (action == IDiamond.FacetCutAction.Add) {
                addFunctions(facetAddress, functionSelectors);
            } else if (action == IDiamond.FacetCutAction.Replace) {
                replaceFunctions(facetAddress, functionSelectors);
            } else if (action == IDiamond.FacetCutAction.Remove) {
                removeFunctions(facetAddress, functionSelectors);
            } else {
                revert IncorrectFacetCutAction(uint8(action));
            }
        }
        emit IDiamond.DiamondCut(cuts, init, initData);
        initializeDiamondCut(init, initData);
    }

    /// @dev The diamond's own address is accepted only while the diamond is being constructed (it has no code
    /// yet), which is when it registers its own functions.
    function addFunctions(address facetAddress, bytes4[] memory functionSelectors) internal {
        if (facetAddress == address(0)) revert CannotAddSelectorsToZeroAddress(functionSelectors);
        if (facetAddress == address(this)) {
            if (address(this).code.length != 0) revert CannotUseDiamondAsFacet();
        } else {
            enforceHasContractCode(facetAddress, "LibDiamondCut: Add facet has no code");
        }
        DiamondStorage storage ds = diamondStorage();
        uint16 selectorCount = uint16(ds.selectors.length);
        for (uint256 selectorIndex; selectorIndex < functionSelectors.length; selectorIndex++) {
            bytes4 selector = functionSelectors[selectorIndex];
            address oldFacetAddress = ds.facetAddressAndSelectorPosition[selector].facetAddress;
            if (oldFacetAddress != address(0)) revert CannotAddFunctionToDiamondThatAlreadyExists(selector);
            ds.facetAddressAndSelectorPosition[selector] =
                FacetAddressAndSelectorPosition({facetAddress: facetAddress, selectorPosition: selectorCount});
            ds.selectors.push(selector);
            selectorCount++;
        }
    }

    function replaceFunctions(address facetAddress, bytes4[] memory functionSelectors) internal {
        DiamondStorage storage ds = diamondStorage();
        if (facetAddress == address(0)) revert CannotReplaceFunctionsFromFacetWithZeroAddress(functionSelectors);
        if (facetAddress == address(this)) revert CannotUseDiamondAsFacet();
        enforceHasContractCode(facetAddress, "LibDiamondCut: Replace facet has no code");
        for (uint256 selectorIndex; selectorIndex < functionSelectors.length; selectorIndex++) {
            bytes4 selector = functionSelectors[selectorIndex];
            address oldFacetAddress = ds.facetAddressAndSelectorPosition[selector].facetAddress;
            if (oldFacetAddress == address(this)) revert CannotReplaceImmutableFunction(selector);
            if (oldFacetAddress == facetAddress) {
                revert CannotReplaceFunctionWithTheSameFunctionFromTheSameFacet(selector);
            }
            if (oldFacetAddress == address(0)) revert CannotReplaceFunctionThatDoesNotExists(selector);
            ds.facetAddressAndSelectorPosition[selector].facetAddress = facetAddress;
        }
    }

    function removeFunctions(address facetAddress, bytes4[] memory functionSelectors) internal {
        DiamondStorage storage ds = diamondStorage();
        uint256 selectorCount = ds.selectors.length;
        if (facetAddress != address(0)) revert RemoveFacetAddressMustBeZeroAddress(facetAddress);
        for (uint256 selectorIndex; selectorIndex < functionSelectors.length; selectorIndex++) {
            bytes4 selector = functionSelectors[selectorIndex];
            FacetAddressAndSelectorPosition memory old = ds.facetAddressAndSelectorPosition[selector];
            if (old.facetAddress == address(0)) revert CannotRemoveFunctionThatDoesNotExist(selector);
            if (old.facetAddress == address(this)) revert CannotRemoveImmutableFunction(selector);
            // Move the last selector into the removed one's position.
            selectorCount--;
            if (old.selectorPosition != selectorCount) {
                bytes4 lastSelector = ds.selectors[selectorCount];
                ds.selectors[old.selectorPosition] = lastSelector;
                ds.facetAddressAndSelectorPosition[lastSelector].selectorPosition = old.selectorPosition;
            }
            ds.selectors.pop();
            delete ds.facetAddressAndSelectorPosition[selector];
        }
    }

    function initializeDiamondCut(address init, bytes memory initData) internal {
        if (init == address(0)) return;
        enforceHasContractCode(init, "LibDiamondCut: _init address has no code");
        (bool success, bytes memory error) = init.delegatecall(initData);
        if (!success) {
            if (error.length > 0) {
                assembly ("memory-safe") {
                    revert(add(32, error), mload(error))
                }
            }
            revert InitializationFunctionReverted(init, initData);
        }
    }

    function enforceHasContractCode(address target, string memory errorMessage) internal view {
        if (target.code.length == 0) revert NoBytecodeAtAddress(target, errorMessage);
    }
}
